PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
ASK {
  SELECT ?countEur ?countAs ?isGreater
  WHERE {
    { SELECT (COUNT(?country) AS ?countEur) WHERE { ?country wdt:P30 wd:Q46 ?country . FILTER(EXISTS { ?country wdt:P27 wd:Q46 }) } }
    { SELECT (COUNT(?country) AS ?countAs) WHERE { ?country wdt:P30 wd:Q62 ?country . FILTER(EXISTS { ?country wdt:P27 wd:Q62 }) } }
    BIND(?countEur > ?countAs AS ?isGreater)
  }
  FILTER(?isGreater = true)
}

