  }
  {
    SELECT (COUNT(?c3) AS ?countAsia) WHERE {
      ?c3 wdt:P27 wd:Q62 ?c4.
      ?c4 wdt:P17 wd:Q62.
    } GROUP BY ?c4
  }
}
FILTER(?countEurope > ?countAsia)

