PREFIX wd: <http://www.wikidata.org/entity/> 
PREFIX wdt: <http://www.wikidata.org/prop/direct/> 
PREFIX pq: <http://www.wikidata.org/prop/qualifier/> 
PREFIX p: <http://www.wikidata.org/prop/> 
PREFIX ps: <http://www.wikidata.org/prop/statement/> 
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?winner WHERE {
  {
    SELECT ?player (COUNT(?award) AS ?count) WHERE {
      ?player wdt:P31 wd:Q5 .
      ?player wdt:P134 wd:Q41421 .
      ?award wdt:P31 wd:Q19020 .
      ?award wdt:P734 ?player .
    }
    GROUP BY ?player
  } AS %jordan
  UNION
  {
    SELECT ?player (COUNT(?award) AS ?count) WHERE {
      ?player wdt:P31 wd:Q5 .
      ?player wdt:P134 wd:Q25369 .
      ?award wdt:P31 wd:Q19020 .
      ?award wdt:P734 ?player .
    }
    GROUP BY ?player
  } AS %bryant
  {
    SELECT ?player (MAX(?count) AS ?max_count) WHERE {
      INCLUDE %jordan
      INCLUDE %bryant
    }
    GROUP BY ?player
  } AS %max
  INCLUDE %jordan
  INCLUDE %bryant
  BIND(?count AS ?final_count)
  BIND(?max_count AS ?max_count)
  BIND(IF(?final_count > ?max_count, ?player, wd:Q0) AS ?winner)
}

